import pandas as pd
from io import StringIO

def solve(data):
     df = pd.read_csv(StringIO(data['text']), sep=';', dtype={'id':'string'}, na_values=['missing'])
     return {'ids': df['id'].tolist(), 'amounts': [None if pd.isna(v) else float(v) for v in df['amount']]}
